CREATE TABLE billing_events(id TEXT PRIMARY KEY,event_type TEXT NOT NULL,provider_created INTEGER NOT NULL,fingerprint TEXT NOT NULL,payload BLOB NOT NULL,state TEXT NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','processed','ignored')),received_at INTEGER NOT NULL);
CREATE INDEX billing_events_pending ON billing_events(state,received_at);
CREATE TABLE billing_customers(workspace_id TEXT PRIMARY KEY REFERENCES workspaces(id),request_id TEXT NOT NULL UNIQUE,actor_id TEXT NOT NULL REFERENCES users(id),email TEXT NOT NULL,customer_id TEXT UNIQUE,created_at INTEGER NOT NULL);
CREATE TABLE billing_plans(id TEXT PRIMARY KEY,price_id TEXT NOT NULL,enabled INTEGER NOT NULL CHECK(enabled IN (0,1)),price_snapshot BLOB,price_observed INTEGER NOT NULL DEFAULT 0,next_refresh INTEGER NOT NULL DEFAULT 0,price_generation INTEGER NOT NULL DEFAULT 0);
CREATE TABLE billing_checkouts(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),actor_id TEXT NOT NULL REFERENCES users(id),customer_id TEXT NOT NULL REFERENCES billing_customers(customer_id),plan_id TEXT NOT NULL REFERENCES billing_plans(id),price_id TEXT NOT NULL,session_id TEXT UNIQUE,checkout_url TEXT NOT NULL DEFAULT '',state TEXT NOT NULL CHECK(state IN ('pending','open','completed','expired')),created_at INTEGER NOT NULL,hosting_limits BLOB);
CREATE UNIQUE INDEX billing_checkout_active ON billing_checkouts(workspace_id) WHERE state IN ('pending','open','completed');
CREATE TABLE billing_subscriptions(id TEXT PRIMARY KEY,checkout_id TEXT NOT NULL UNIQUE REFERENCES billing_checkouts(id),workspace_id TEXT NOT NULL REFERENCES workspaces(id),customer_id TEXT NOT NULL REFERENCES billing_customers(customer_id),plan_id TEXT NOT NULL REFERENCES billing_plans(id),price_id TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'awaiting_reconciliation',first_event TEXT NOT NULL REFERENCES billing_events(id),reconciliation_generation INTEGER NOT NULL DEFAULT 0,snapshot BLOB);
CREATE TABLE billing_work(kind TEXT NOT NULL CHECK(kind IN ('customer','checkout','event','subscription')),reference TEXT NOT NULL,next_attempt INTEGER NOT NULL DEFAULT 0,attempts INTEGER NOT NULL DEFAULT 0,lease_hash TEXT NOT NULL DEFAULT '',lease_until INTEGER NOT NULL DEFAULT 0,done INTEGER NOT NULL DEFAULT 0 CHECK(done IN (0,1)),PRIMARY KEY(kind,reference));
CREATE INDEX billing_work_due ON billing_work(done,next_attempt,lease_until);
CREATE TABLE billing_charges(id TEXT PRIMARY KEY,generation INTEGER NOT NULL DEFAULT 0,subscription_id TEXT REFERENCES billing_subscriptions(id),customer_id TEXT REFERENCES billing_customers(customer_id),invoice_id TEXT NOT NULL DEFAULT '',payment_intent_id TEXT NOT NULL DEFAULT '',snapshot BLOB,next_refresh INTEGER NOT NULL DEFAULT 0);
CREATE INDEX billing_charges_subscription ON billing_charges(subscription_id);
CREATE INDEX billing_charges_refresh ON billing_charges(next_refresh);
CREATE TABLE hosting_plan_limits(plan_id TEXT PRIMARY KEY REFERENCES billing_plans(id),projects INTEGER NOT NULL CHECK(projects BETWEEN 1 AND 100),uploads INTEGER NOT NULL CHECK(uploads BETWEEN 1 AND 20),upload_bytes INTEGER NOT NULL CHECK(upload_bytes BETWEEN 1 AND 104857600),node INTEGER NOT NULL CHECK(node IN (0,1)));
